15	const projectionPartitionCentroidWarningThreshold = 0.7
16	
17	func buildNativeTestBlockRunner(prog *dsl.Program) (dsl.TestBlockRunner, error) {
18		if prog == nil {
19			return nil, fmt.Errorf("program is nil")
20		}
21	
22		cfg, compileErrs := dsl.CompileAST(prog)
23		if len(compileErrs) > 0 {
24			return nil, fmt.Errorf("TEST block compile failed: %v", compileErrs)
25		}
26	
27		categoryMapping, piiMapping, jailbreakMapping, err := loadClassifierMappings(cfg)
28		if err != nil {
