39	func loadClassifierMappings(
40		cfg *config.RouterConfig,
41	) (
42		*classification.CategoryMapping,
43		*classification.PIIMapping,
44		*classification.JailbreakMapping,
45		error,
46	) {
47		var (
48			categoryMapping  *classification.CategoryMapping
49			piiMapping       *classification.PIIMapping
50			jailbreakMapping *classification.JailbreakMapping
51			err              error
52		)
53	
54		if cfg.CategoryMappingPath != "" {
55			categoryMapping, err = classification.LoadCategoryMapping(cfg.CategoryMappingPath)
56			if err != nil {
57				return nil, nil, nil, fmt.Errorf("failed to load category mapping: %w", err)
58			}
59		}
60	
61		if cfg.PIIMappingPath != "" {
62			piiMapping, err = classification.LoadPIIMapping(cfg.PIIMappingPath)
63			if err != nil {
64				return nil, nil, nil, fmt.Errorf("failed to load PII mapping: %w", err)
65			}
66		}
67	
68		if cfg.PromptGuard.JailbreakMappingPath != "" {
69			jailbreakMapping, err = classification.LoadJailbreakMapping(cfg.PromptGuard.JailbreakMappingPath)
70			if err != nil {
71				return nil, nil, nil, fmt.Errorf("failed to load jailbreak mapping: %w", err)
72			}
73		}
74	
75		return categoryMapping, piiMapping, jailbreakMapping, nil
76	}
77	
78	func (r *nativeTestBlockRunner) EvaluateTestBlockQuery(query string) (*dsl.TestBlockResult, error) {
79		signals, err := r.classifier.EvaluateAllSignalsWithHeaders(classification.SignalEvaluationInput{
80			Text:            query,
81			ContextText:     query,
82			CurrentUserText: query,
83		})
84		if err != nil {
85			return nil, err
86		}
87	
88		result, err := r.classifier.EvaluateDecisionWithEngine(signals)
89		if err != nil {
90			return nil, err
91		}
92		if result == nil || result.Decision == nil {
93			return nil, nil
94		}
95	
96		return &dsl.TestBlockResult{
97			DecisionName: result.Decision.Name,
98			Confidence:   result.Confidence,
99			MatchedRules: append([]string(nil), result.MatchedRules...),
100		}, nil
101	}
102	
103	func (r *nativeTestBlockRunner) ValidateProjectionPartitions(
104		prog *dsl.Program,
105	) []dsl.Diagnostic {
106		if r == nil || r.classifier == nil || prog == nil {
107			return nil
108		}
109	
110		warnings, err := r.classifier.AnalyzeSoftmaxSignalGroupCentroids(projectionPartitionCentroidWarningThreshold)
111		if err != nil {
112			return []dsl.Diagnostic{{
113				Level:   dsl.DiagError,
114				Message: fmt.Sprintf("PROJECTION partition native centroid validation failed: %v", err),
115				Pos:     firstSoftmaxProjectionPartitionPos(prog),
116			}}
117		}
118		if len(warnings) == 0 {
119			return nil
120		}
121	
122		positions := projectionPartitionPositions(prog)
123		diags := make([]dsl.Diagnostic, 0, len(warnings))
124		for _, warning := range warnings {
125			diags = append(diags, dsl.Diagnostic{
126				Level: dsl.DiagWarning,
127				Pos:   positions[warning.GroupName],
128				Message: fmt.Sprintf(
129					`PROJECTION partition %s: members %q and %q candidate centroids have cosine similarity %.2f (threshold: %.1f) — softmax scores may be near-uniform on ambiguous queries`,
130					warning.GroupName,
131					warning.LeftMember,
132					warning.RightMember,
133					warning.Similarity,
134					projectionPartitionCentroidWarningThreshold,
135				),
136			})
137		}
138		return diags
139	}
140	
141	func projectionPartitionPositions(prog *dsl.Program) map[string]dsl.Position {
142		positions := make(map[string]dsl.Position, len(prog.ProjectionPartitions))
143		for _, partition := range prog.ProjectionPartitions {
144			positions[partition.Name] = partition.Pos
145		}
146		return positions
147	}
148	
149	func firstSoftmaxProjectionPartitionPos(prog *dsl.Program) dsl.Position {
150		for _, partition := range prog.ProjectionPartitions {
151			if partition.Semantics == "softmax_exclusive" {
152				return partition.Pos
153			}
154		}
155		return dsl.Position{}
156	}
