1	package dsl
2	
3	import (
4		"fmt"
5		"strings"
6	)
7	
8	// TestBlockResult is the runtime routing result for one TEST query.
9	type TestBlockResult struct {
10		DecisionName string
11		Confidence   float64
12		MatchedRules []string
13	}
14	
15	// TestBlockRunner evaluates one query against the routing signal pipeline.
16	type TestBlockRunner interface {
17		EvaluateTestBlockQuery(query string) (*TestBlockResult, error)
18	}
19	
20	// ProjectionPartitionRuntimeValidator emits native diagnostics that require runtime
21	// signal analysis beyond static AST validation.
22	type ProjectionPartitionRuntimeValidator interface {
23		ValidateProjectionPartitions(prog *Program) []Diagnostic
24	}
25	
26	// ValidateTestBlocks evaluates TEST blocks with a runtime runner and emits diagnostics
27	// for mismatches or runtime failures. Static TEST block diagnostics remain in the main validator.
28	func ValidateTestBlocks(prog *Program, runner TestBlockRunner) []Diagnostic {
29		if prog == nil || runner == nil || len(prog.TestBlocks) == 0 {
30			return nil
31		}
32	
33		routeNames := make(map[string]bool, len(prog.Routes))
34		for _, route := range prog.Routes {
35			routeNames[route.Name] = true
36		}
37	
38		diagnostics := make([]Diagnostic, 0)
39		for _, tb := range prog.TestBlocks {
40			for _, entry := range tb.Entries {
41				if !shouldEvaluateTestEntry(entry, routeNames) {
42					continue
43				}
44				if diag := validateTestEntry(tb, entry, runner); diag != nil {
45					diagnostics = append(diagnostics, *diag)
46				}
47			}
48		}
49	
50		return diagnostics
51	}
52	
53	func shouldEvaluateTestEntry(entry *TestEntry, routeNames map[string]bool) bool {
54		return entry.Query != "" && routeNames[entry.RouteName]
55	}
56	
57	func validateTestEntry(tb *TestBlockDecl, entry *TestEntry, runner TestBlockRunner) *Diagnostic {
58		result, err := runner.EvaluateTestBlockQuery(entry.Query)
59		if err != nil {
60			return runtimeTestFailureDiagnostic(tb.Name, entry, err)
61		}
62		if result == nil || strings.TrimSpace(result.DecisionName) == "" {
63			return missingRuntimeRouteDiagnostic(tb.Name, entry)
64		}
65		if result.DecisionName == entry.RouteName {
66			return nil
67		}
68		return mismatchedRuntimeRouteDiagnostic(tb.Name, entry, result)
69	}
70	
71	func runtimeTestFailureDiagnostic(testName string, entry *TestEntry, err error) *Diagnostic {
72		return &Diagnostic{
73			Level: DiagError,
74			Pos:   entry.Pos,
75			Message: fmt.Sprintf(
76				"TEST %s: runtime evaluation failed for %q: %v",
77				testName,
78				entry.Query,
79				err,
80			),
81		}
82	}
83	
84	func missingRuntimeRouteDiagnostic(testName string, entry *TestEntry) *Diagnostic {
85		return &Diagnostic{
86			Level: DiagError,
87			Pos:   entry.Pos,
88			Message: fmt.Sprintf(
89				"TEST %s: query %q expected route %q, got no matching route",
90				testName,
91				entry.Query,
92				entry.RouteName,
93			),
94		}
95	}
96	
97	func mismatchedRuntimeRouteDiagnostic(testName string, entry *TestEntry, result *TestBlockResult) *Diagnostic {
98		return &Diagnostic{
99			Level: DiagError,
100			Pos:   entry.Pos,
101			Message: fmt.Sprintf(
